//! Parser regression tests using **inline** on-chain account samples (base64).
//! We do not commit `data/pool-snapshots/*.jsonl` — workspace `data/` is gitignored and
//! snapshot pipelines stay out of the repo.

use base64::Engine;

/// One captured Raydium pool account (`data_b64` from collector output); used only to exercise `parse_pool_state`.
const RAYDIUM_POOL_ACCOUNT_DATA_B64: &str = "";

/// One captured Meteora LB pair account (`data_b64` from collector output); used only to exercise `parse_lb_pair`.
const METEORA_LB_PAIR_ACCOUNT_DATA_B64: &str = "";

#[test]
fn raydium_fixture_decodes_pool_state() -> anyhow::Result<()> {
    let data = base64::engine::general_purpose::STANDARD.decode(RAYDIUM_POOL_ACCOUNT_DATA_B64)?;
    clmm_lp_protocols::raydium::pool_reader::parse_pool_state(&data)?;
    Ok(())
}

#[test]
fn meteora_fixture_decodes_lb_pair() -> anyhow::Result<()> {
    let data =
        base64::engine::general_purpose::STANDARD.decode(METEORA_LB_PAIR_ACCOUNT_DATA_B64)?;
    clmm_lp_protocols::meteora::pool_reader::parse_lb_pair(&data)?;
    Ok(())
}
